dashboard.definition:
{
    "title": "Splunk General Hospital – Situation Overview",
    "description": "SAKH hospital overview: free beds by building and ward, care situation and infrastructure health",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Time range",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        }
    },
    "dataSources": {
        "ds_beds": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"sakh:kis:beds\" earliest=-15m\n| stats latest(beds_total) as beds_total latest(occupied) as occupied latest(free) as free latest(occupancy_pct) as occupancy_pct latest(floor) as floor latest(ward_name) as ward_name by ward building department",
                "enableSmartSources": true
            },
            "name": "Bed status (last 15 min)"
        },
        "ds_k_free": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_beds",
                "query": "| stats sum(free) as \"Free beds\""
            }
        },
        "ds_k_occ": {
            "type": "ds.search",
            "options": {
                "query": "| mstats sum(sakh.beds.occupied) as o sum(sakh.beds.beds_total) as t WHERE index=demo_sakh_en_metrics span=15m\n| eval \"Occupancy %\"=round(100 * o / t, 1) | fields _time \"Occupancy %\"",
                "enableSmartSources": true
            },
            "name": "Occupancy trend"
        },
        "ds_k_ed": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as w WHERE index=demo_sakh_en_metrics metric_name=\"sakh.ed.waiting\" span=10m | rename w as \"Waiting\"",
                "enableSmartSources": true
            }
        },
        "ds_k_blood": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"sakh:bloodbank:inventory\" earliest=-20m | stats latest(status) as status by product blood_group | where status=\"critical\" | stats count as \"Critical blood stock\"",
                "enableSmartSources": true
            }
        },
        "ds_k_inc": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"snow:incident\" earliest=-48h | stats latest(state) as state latest(priority) as priority by number | where priority<=2 AND state!=\"Resolved\" | stats count as \"Open P1/P2\"",
                "enableSmartSources": true
            }
        },
        "ds_k_net": {
            "type": "ds.search",
            "options": {
                "query": "| mstats latest(_value) as v WHERE index=demo_sakh_en_metrics metric_name=\"sakh.network.reachable\" BY device | where v=0 | stats count as \"Network offline\"",
                "enableSmartSources": true
            }
        },
        "ds_rings": {
            "type": "ds.search",
            "options": {
                "query": "| mstats latest(_value) as v WHERE index=demo_sakh_en_metrics metric_name=\"sakh.beds.occupancy_pct\" BY ward\n| stats avg(v) as beds\n| appendcols [| mstats latest(_value) as v WHERE index=demo_sakh_en_metrics metric_name=\"sakh.ed.waiting\" | stats max(v) as ed]\n| appendcols [| mstats latest(_value) as v WHERE index=demo_sakh_en_metrics metric_name=\"sakh.blood.fill_pct\" product=\"EK\" BY blood_group | stats min(v) as blood]\n| appendcols [| mstats latest(_value) as v WHERE index=demo_sakh_en_metrics metric_name=\"sakh.medtech.online\" BY device_id | stats avg(v) as medtech | eval medtech=round(100*medtech, 1)]\n| appendcols [| mstats latest(_value) as v WHERE index=demo_sakh_en_metrics metric_name=\"sakh.network.reachable\" BY device | stats avg(v) as net | eval net=round(100*net, 1)]\n| appendcols [| mstats latest(_value) as v WHERE index=demo_sakh_en_metrics metric_name=\"sakh.hl7.queue_depth\" BY channel | stats sum(v) as hl7]\n| appendcols [| mstats latest(_value) as v WHERE index=demo_sakh_en_metrics metric_name=\"sakh.db.avg_query_ms\" instance=\"KISPRD\" | stats max(v) as kisdb]\n| eval r=mvappend(\"Bed occupancy;\".coalesce(tostring(round(beds, 1)), \"\").\";%;0;100;88;95;lower;kis_beds\", \"ED waiting;\".coalesce(tostring(ed), \"\").\";;0;80;15;30;lower;kis_ed\", \"Blood RBC min. fill;\".coalesce(tostring(round(blood, 0)), \"\").\";%;0;120;45;25;higher;kis_blood\", \"Medical devices online;\".coalesce(tostring(medtech), \"\").\";%;0;100;98;90;higher;kis_medtech\", \"Network reachable;\".coalesce(tostring(net), \"\").\";%;0;100;99;95;higher;kis_network\", \"HL7 queue;\".coalesce(tostring(hl7), \"\").\";;0;500;50;200;lower;kis_integration\", \"HIS DB query;\".coalesce(tostring(round(kisdb, 0)), \"\").\";ms;0;200;20;60;lower;kis_servers\")\n| mvexpand r\n| eval f=split(r, \";\"), name=mvindex(f, 0), value=mvindex(f, 1), unit=mvindex(f, 2), min=mvindex(f, 3), max=mvindex(f, 4), warn=mvindex(f, 5), crit=mvindex(f, 6), better=mvindex(f, 7), key=mvindex(f, 8)\n| table name value unit min max warn crit better key",
                "enableSmartSources": true
            },
            "name": "Health by area"
        },
        "ds_ring_kis_beds": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_rings",
                "query": "| where key=\"kis_beds\""
            }
        },
        "ds_ring_kis_ed": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_rings",
                "query": "| where key=\"kis_ed\""
            }
        },
        "ds_ring_kis_blood": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_rings",
                "query": "| where key=\"kis_blood\""
            }
        },
        "ds_ring_kis_medtech": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_rings",
                "query": "| where key=\"kis_medtech\""
            }
        },
        "ds_ring_kis_network": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_rings",
                "query": "| where key=\"kis_network\""
            }
        },
        "ds_ring_kis_integration": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_rings",
                "query": "| where key=\"kis_integration\""
            }
        },
        "ds_ring_kis_servers": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_rings",
                "query": "| where key=\"kis_servers\""
            }
        },
        "ds_trend": {
            "type": "ds.search",
            "options": {
                "query": "| mstats sum(sakh.beds.occupied) as o sum(sakh.beds.beds_total) as t WHERE index=demo_sakh_en_metrics BY building span=15m\n| eval pct=round(100 * o / t, 1), building=\"Building \".building\n| timechart span=15m avg(pct) by building",
                "enableSmartSources": true
            },
            "name": "Occupancy by building"
        },
        "ds_incidents": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"snow:incident\" earliest=-48h\n| stats latest(state) as Status latest(priority_label) as Priority latest(short_description) as Description latest(assignment_group) as Group latest(business_service) as Service latest(_time) as t by number\n| where Status!=\"Resolved\" | sort Priority - t | head 12\n| eval Time=strftime(t, \"%m/%d %H:%M\") | table Time number Priority Status Service Group Description | rename number as Incident",
                "enableSmartSources": true
            },
            "name": "Open incidents"
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_clinic/images/nav_home_on.svg",
                "preserveAspectRatio": true
            }
        },
        "viz_nav_care": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_clinic/images/nav_care.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_clinic",
                        "dashboard": "kis_beds",
                        "tokens": [],
                        "newTab": false
                    }
                }
