        "viz_16": {
            "type": "splunk.table",
            "dataSources": {
                "primary": "ds_incidents"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 10,
                "headerVisibility": "fixed",
                "fontSize": "small",
                "tableFormat": {
                    "rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBg)",
                    "headerBackgroundColor": "#e9eef4",
                    "rowColors": "#13294b",
                    "headerColor": "#5b6878"
                },
                "columnFormat": {
                    "Status": {
                        "rowBackgroundColors": "> table | seriesByName(\"Status\") | matchValue(statusBg)"
                    }
                }
            },
            "context": {
                "rowBg": [
                    "#ffffff",
                    "#f5f7fa"
                ],
                "statusBg": [
                    {
                        "match": "Critical",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "Degraded",
                        "value": "#fcefcc"
                    },
                    {
                        "match": "Healthy",
                        "value": "#d9f0e3"
                    },
                    {
                        "match": "critical",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "high",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "error",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "warning",
                        "value": "#fcefcc"
                    },
